package com.mycompany.rentalmanagement.util;
import java.math.BigDecimal;import java.time.LocalDate;
public final class ValidationUtil {private ValidationUtil(){} public static String text(String s,String label,int max){s=s==null?"":s.trim();if(s.isEmpty())throw new IllegalArgumentException(label+" is required.");if(s.length()>max)throw new IllegalArgumentException(label+" must be at most "+max+" characters.");return s;} public static BigDecimal money(String s,String label){try{BigDecimal n=new BigDecimal(s);if(n.signum()<0)throw new Exception();return n.setScale(2,java.math.RoundingMode.HALF_UP);}catch(Exception e){throw new IllegalArgumentException(label+" must be a valid non-negative amount.");}} public static LocalDate date(String s,String label){try{return LocalDate.parse(s);}catch(Exception e){throw new IllegalArgumentException(label+" must be a valid date.");}}}
